import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv_transpose2d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
__device__ __forceinline__ int floor_div(int a, int b) {
    int q = a / b;
    int r = a - q * b;
    if (r != 0 && ((r < 0) != (b < 0))) {
        q -= 1;
    }
    return q;
}
#define TILE_H 16
#define TILE_W 16
#define OW_PER_THREAD 2
__global__ void conv_transpose2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    const int batch_size,
    const int in_channels,
    const int out_channels,
    const int in_h,
    const int in_w,
    const int out_h,
    const int out_w,
    const int kH,
    const int kW,
    const int stride_h,
    const int stride_w,
    const int pad_h,
    const int pad_w,
    const int dil_h,
    const int dil_w,
    const int groups,
    const int in_channels_per_group,
    const int out_channels_per_group,
    const int in_tile_h,
    const int in_tile_w
) {
    extern __shared__ float smem[]; // size: in_channels_per_group * in_tile_h * in_tile_w
    int tx = threadIdx.x; // 0..TILE_W-1
    int ty = threadIdx.y; // 0..TILE_H-1
    int ow0 = blockIdx.x * TILE_W * OW_PER_THREAD;
    int oh0 = blockIdx.y * TILE_H;
    int bz = blockIdx.z;
    int n = bz / groups;
    int g = bz % groups;
    int oh = oh0 + ty;
    int ow = ow0 + tx;
    // base of the required input tile for this block (safe upper-bound sized)
    int ih_min = floor_div(oh0 + pad_h - (kH - 1) * dil_h, stride_h);
    int iw_min = floor_div(ow0 + pad_w - (kW - 1) * dil_w, stride_w);
    int tile_size = in_channels_per_group * in_tile_h * in_tile_w;
    int tid = ty * TILE_W + tx;
    int nthreads = TILE_W * TILE_H;
    for (int idx = tid; idx < tile_size; idx += nthreads) {
        int iw_off = idx % in_tile_w;
        int tmp = idx / in_tile_w;
        int ih_off = tmp % in_tile_h;
        int ic_local = tmp / in_tile_h;
        int ih = ih_min + ih_off;
        int iw = iw_min + iw_off;
        int ic = g * in_channels_per_group + ic_local;
        float val = 0.0f;
        if (ih >= 0 && ih < in_h && iw >= 0 && iw < in_w) {
            int input_idx = ((n * in_channels + ic) * in_h + ih) * in_w + iw;
            val = input[input_idx];
        }
        smem[(ic_local * in_tile_h + ih_off) * in_tile_w + iw_off] = val;
    }
    __syncthreads();
    if (oh < out_h) {
        int ow0v = ow0 + tx;
        int ow1v = ow0 + tx + TILE_W;
        bool valid0 = ow0v < out_w;
        bool valid1 = ow1v < out_w;
        for (int oc_in_group = 0; oc_in_group < out_channels_per_group; ++oc_in_group) {
            float acc0 = 0.0f;
            float acc1 = 0.0f;
            int oc = g * out_channels_per_group + oc_in_group;
            for (int kh = 0; kh < kH; ++kh) {
                int oh_off = oh + pad_h - kh * dil_h;
                if (oh_off % stride_h != 0) continue;
                int ih = oh_off / stride_h;
                int ih_offset = ih - ih_min;
                if (ih_offset < 0 || ih_offset >= in_tile_h) continue;
                for (int kw = 0; kw < kW; ++kw) {
                    bool kw_valid0 = false, kw_valid1 = false;
                    int iw_offset0 = -1, iw_offset1 = -1;
                    if (valid0) {
                        int ow_off0 = ow0v + pad_w - kw * dil_w;
                        if (ow_off0 % stride_w == 0) {
                            int iw0 = ow_off0 / stride_w;
                            int off0 = iw0 - iw_min;
                            if (off0 >= 0 && off0 < in_tile_w) {
                                iw_offset0 = off0;
                                kw_valid0 = true;
                            }
                        }
                    }
                    if (valid1) {
                        int ow_off1 = ow1v + pad_w - kw * dil_w;
                        if (ow_off1 % stride_w == 0) {
                            int iw1 = ow_off1 / stride_w;
                            int off1 = iw1 - iw_min;
                            if (off1 >= 0 && off1 < in_tile_w) {
                                iw_offset1 = off1;
                                kw_valid1 = true;
                            }
                        }
                    }
                    if (!kw_valid0 && !kw_valid1) continue;
                    for (int ic_local = 0; ic_local < in_channels_per_group; ++ic_local) {
                        int weight_idx = (((g * in_channels_per_group + ic_local) * out_channels_per_group + oc_in_group) * kH + kh) * kW + kw;
                        float wv = weight[weight_idx];
                        if (kw_valid0) {
                            float in_val0 = smem[(ic_local * in_tile_h + ih_offset) * in_tile_w + iw_offset0];
                            acc0 += in_val0 * wv;
                        }
                        if (kw_valid1) {
                            float in_val1 = smem[(ic_local * in_tile_h + ih_offset) * in_tile_w + iw_offset1];
                            acc1 += in_val1 * wv;
                        }
                    }
                }
            }
            if (valid0) {
                int out_idx0 = ((n * out_channels + oc) * out_h + oh) * out_w + ow0v;
                output[out_idx0] = acc0;
            }
            if (valid1) {
                int out_idx1 = ((n * out_channels + oc) * out_h + oh) * out_w + ow1v;
                output[out_idx1] = acc1;
            }
        }
    }
}
torch::Tensor conv_transpose2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int groups
) {
    input = input.contiguous();
    weight = weight.contiguous();
    const int batch_size = input.size(0);
    const int in_channels = input.size(1);
    const int in_h = input.size(2);
    const int in_w = input.size(3);
    const int kH = weight.size(2);
    const int kW = weight.size(3);
    const int out_channels_per_group = weight.size(1);
    const int out_channels = out_channels_per_group * groups;
    const int in_channels_per_group = in_channels / groups;
    const int out_h = (in_h - 1) * stride_h - 2 * pad_h + dil_h * (kH - 1) + 1;
    const int out_w = (in_w - 1) * stride_w - 2 * pad_w + dil_w * (kW - 1) + 1;
    auto output = torch::zeros({batch_size, out_channels, out_h, out_w}, input.options());
    // safe upper bound for the required input tile size along each dimension
    int in_tile_h = (TILE_H - 1 + (kH - 1) * dil_h + stride_h - 1) / stride_h + 2;
    int in_tile_w = (TILE_W * OW_PER_THREAD - 1 + (kW - 1) * dil_w + stride_w - 1) / stride_w + 2;
    dim3 block(TILE_W, TILE_H);
    dim3 grid(
        (out_w + TILE_W * OW_PER_THREAD - 1) / (TILE_W * OW_PER_THREAD),
        (out_h + TILE_H - 1) / TILE_H,
        batch_size * groups
    );
    size_t smem_bytes = (size_t)in_channels_per_group * in_tile_h * in_tile_w * sizeof(float);
    conv_transpose2d_kernel<<<grid, block, smem_bytes>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        in_h,
        in_w,
        out_h,
        out_w,
        kH,
        kW,
        stride_h,
        stride_w,
        pad_h,
        pad_w,
        dil_h,
        dil_w,
        groups,
        in_channels_per_group,
        out_channels_per_group,
        in_tile_h,
        in_tile_w
    );
    return output;
}
"""

conv_transpose2d_cpp_source = r"""
torch::Tensor conv_transpose2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int groups
);
"""

conv_transpose2d_module = load_inline(
    name="conv_transpose2d_module",
    cpp_sources=conv_transpose2d_cpp_source,
    cuda_sources=conv_transpose2d_source,
    functions=["conv_transpose2d_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: tuple = (1, 1),
                 padding: tuple = (0, 0), dilation: tuple = (1, 1), groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups

        self.weight = nn.Parameter(
            torch.empty(in_channels, out_channels // groups, kernel_size[0], kernel_size[1])
        )
        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)

        self.has_bias = bias
        if bias:
            self.bias = nn.Parameter(torch.zeros(out_channels))
        else:
            self.register_parameter('bias', None)

        self.conv_transpose2d_cuda = conv_transpose2d_module.conv_transpose2d_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.cuda().contiguous()
        weight = self.weight.cuda().contiguous()

        output = self.conv_transpose2d_cuda(
            x, weight,
            self.stride[0], self.stride[1],
            self.padding[0], self.padding[1],
            self.dilation[0], self.dilation[1],
            self.groups
        )

        if self.has_bias:
            output = output + self.bias.view(1, -1, 1, 1)

        return output


